import React, { useState } from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import {
  Box,
  Drawer,
  AppBar,
  Toolbar,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  IconButton,
  Avatar,
  Menu,
  MenuItem,
  Divider,
  Tooltip,
  Chip,
  Badge,
  Dialog,
  DialogTitle,
  DialogContent,
   DialogActions,
   Button,
   Paper,
 } from '@mui/material';
import {
  Menu as MenuIcon,
  Dashboard as DashboardIcon,
  PointOfSale as PointOfSaleIcon,
  Inventory as InventoryIcon,
  Restaurant as RestaurantIcon,
  LocalGroceryStore as LocalGroceryStoreIcon,
  ReceiptLong as ReceiptLongIcon,
  TableRestaurant as TableRestaurantIcon,
  Kitchen as KitchenIcon,
  SwapHoriz as SwapHorizIcon,
  Assessment as AssessmentIcon,
  AccountBalance as AccountBalanceIcon,
  CreditCard as CreditCardIcon,
  Logout as LogoutIcon,
  Person as PersonIcon,
  Store as StoreIcon,
  Print as PrintIcon,
  PriceChange as PriceChangeIcon,
  Warning as WarningIcon,
  AttachMoney as AttachMoneyIcon,
  MenuBook as MenuBookIcon,
  ChevronRight as ChevronRightIcon,
  Notifications as NotificationsIcon,
  AccountBalance as CashIcon,
} from '@mui/icons-material';
import { useAuth } from '@/hooks/useAuth';
import { usePdv } from '@/contexts/PdvContext';
import { brand } from '@/theme';
import { apiBuffet } from '@/services/api';

const drawerWidth = 260;
const triggerWidth = 12;

const menuItems = [
  { text: 'Dashboard', icon: <DashboardIcon />, path: '/dashboard' },
  { text: 'PDV', icon: <PointOfSaleIcon />, path: '/pdv', roles: ['PDV', 'ADMIN', 'CAIXA'] },
  { text: 'Vendas', icon: <ReceiptLongIcon />, path: '/vendas', roles: ['PDV', 'ADMIN', 'CAIXA', 'GERENTE'] },
  { text: 'Sessões de Caixa', icon: <AttachMoneyIcon />, path: '/sessoes-caixa', roles: ['ADMIN', 'GERENTE', 'CAIXA'] },
  { text: 'Caderno (Fiado)', icon: <MenuBookIcon />, path: '/caderno', roles: ['PDV', 'ADMIN', 'CAIXA', 'GERENTE'] },
  { divider: true, section: 'Fruteira' },
  { text: 'Produtos', icon: <LocalGroceryStoreIcon />, path: '/fruteira/produtos', roles: ['FRUTEIRA', 'ADMIN', 'GERENTE', 'ESTOQUE'] },
  { text: 'Perdas/Quebras', icon: <WarningIcon />, path: '/fruteira/perdas', roles: ['FRUTEIRA', 'ADMIN', 'GERENTE', 'ESTOQUE'] },
  { text: 'Etiquetas Balança', icon: <PrintIcon />, path: '/fruteira/etiquetas', roles: ['FRUTEIRA', 'ADMIN', 'GERENTE'] },
  { text: 'Tabelas de Preço', icon: <PriceChangeIcon />, path: '/fruteira/tabelas-preco', roles: ['FRUTEIRA', 'ADMIN', 'GERENTE'] },
  { divider: true, section: 'Buffet' },
  { text: 'Comandas', icon: <ReceiptLongIcon />, path: '/buffet/comandas', roles: ['BUFFET', 'ADMIN', 'GERENTE', 'CAIXA'] },
  { text: 'Clientes', icon: <PersonIcon />, path: '/buffet/clientes', roles: ['BUFFET', 'ADMIN', 'GERENTE', 'CAIXA'] },
  { text: 'Mesas', icon: <TableRestaurantIcon />, path: '/buffet/mesas', roles: ['BUFFET', 'ADMIN', 'GERENTE'] },
  { text: 'Produtos', icon: <RestaurantIcon />, path: '/buffet/produtos', roles: ['BUFFET', 'ADMIN', 'GERENTE', 'ESTOQUE'] },
  { text: 'Receitas/Fichas Técnicas', icon: <KitchenIcon />, path: '/buffet/receitas', roles: ['BUFFET', 'ADMIN', 'GERENTE'] },
  { text: 'Transferências Estoque', icon: <SwapHorizIcon />, path: '/buffet/transferencias', roles: ['BUFFET', 'ADMIN', 'GERENTE', 'ESTOQUE'] },
  { divider: true, section: 'Estoque' },
  { text: 'Movimentação', icon: <InventoryIcon />, path: '/estoque', roles: ['ESTOQUE', 'ADMIN', 'GERENTE'] },
  { text: 'Inventário', icon: <AssessmentIcon />, path: '/estoque/inventario', roles: ['ESTOQUE', 'ADMIN', 'GERENTE'] },
  { text: 'Alertas', icon: <WarningIcon />, path: '/estoque/alertas', roles: ['ESTOQUE', 'ADMIN', 'GERENTE'] },
  { text: 'Defeitos/Qualidade', icon: <WarningIcon />, path: '/estoque/defeitos', roles: ['ESTOQUE', 'ADMIN', 'GERENTE', 'QUALIDADE'] },
  { divider: true, section: 'Fiscal/Contábil' },
  { text: 'NFC-e/Notas', icon: <ReceiptLongIcon />, path: '/fiscal/nfe', roles: ['FISCAL', 'ADMIN', 'GERENTE', 'CONTABIL'] },
  { text: 'SPED Fiscal', icon: <AccountBalanceIcon />, path: '/fiscal/sped-fiscal', roles: ['FISCAL', 'ADMIN', 'CONTABIL'] },
  { text: 'DRE', icon: <AssessmentIcon />, path: '/fiscal/dre', roles: ['FISCAL', 'ADMIN', 'CONTABIL', 'GERENTE'] },
  { text: 'Ativos Imobilizados', icon: <StoreIcon />, path: '/fiscal/ativos', roles: ['FISCAL', 'ADMIN', 'CONTABIL'] },
  { text: 'Conciliação Cartão', icon: <CreditCardIcon />, path: '/fiscal/conciliacao-cartao', roles: ['FISCAL', 'ADMIN', 'CONTABIL', 'GERENTE'] },
  { text: 'Auditoria', icon: <AssessmentIcon />, path: '/audit', roles: ['ADMIN', 'GERENTE'] },
];

export function Layout() {
  const { user, logout, hasPermission } = useAuth();
  const { selectedPdv, sessaoAtiva } = usePdv();
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [notifOpen, setNotifOpen] = useState(false);
  const [comandasAbertas, setComandasAbertas] = useState<any[]>([]);
  const [selectedComanda, setSelectedComanda] = useState<any | null>(null);
  const [itensComanda, setItensComanda] = useState<any[]>([]);

  const carregarNotificacoes = async () => {
    try {
      const { data } = await apiBuffet.listComandas({ status: 'ABERTA' });
      const list = data?.content ?? (Array.isArray(data) ? data : []);
      setComandasAbertas(list);
      setNotifOpen(true);
    } catch {
      setComandasAbertas([]);
      setNotifOpen(true);
    }
  };

  const verDetalhesComanda = async (comanda: any) => {
    setSelectedComanda(comanda);
    try {
      const { data } = await apiBuffet.listItensComanda(comanda.id);
      setItensComanda(data ?? []);
    } catch {
      setItensComanda([]);
    }
  };

  const handleDrawerToggle = () => setMobileOpen(!mobileOpen);
  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => setAnchorEl(event.currentTarget);
  const handleMenuClose = () => setAnchorEl(null);
  const handleLogout = () => { handleMenuClose(); logout(); navigate('/login'); };

  const filteredMenuItems = menuItems.filter(item => {
    if (item.divider) return true;
    if (!item.roles) return true;
    return item.roles.some(role => hasPermission(role));
  });

  const drawer = (
    <Box sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column', p: 2 }}>
      <Box sx={{ mb: 2, display: 'flex', alignItems: 'center', gap: 1.5, px: 0.5 }}>
        <Box
          component="img"
          src="/logo.png"
          alt="Sistema Tenda"
          sx={{
            height: 52,
            width: 52,
            objectFit: 'contain',
            borderRadius: 2,
            bgcolor: brand.cream,
            p: 0.5,
            flexShrink: 0,
          }}
        />
        <Box sx={{ minWidth: 0 }}>
          <Typography variant="h6" fontWeight={700} sx={{ color: 'text.primary', lineHeight: 1.1 }}>
            Sistema Tenda
          </Typography>
          <Typography variant="caption" color="text.secondary">
            Fruteira &amp; Buffet
          </Typography>
        </Box>
      </Box>
      <Divider />
      <Box sx={{ mb: 2, p: 1.5, bgcolor: 'rgba(245,168,0,0.08)', borderRadius: 2, border: '1px solid rgba(245,168,0,0.18)' }}>
        <Typography variant="caption" color="text.secondary" fontWeight={600}>PDV Ativo</Typography>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          {selectedPdv ? (
            <>
              <Chip label={selectedPdv.codigo} size="small" color="primary" variant="outlined" />
              <Chip label={sessaoAtiva ? 'CAIXA ABERTO' : 'CAIXA FECHADO'} size="small" color={sessaoAtiva ? 'success' : 'default'} variant="outlined" />
            </>
          ) : (
            <Typography variant="body2" color="text.secondary">Nenhum PDV selecionado</Typography>
          )}
        </Box>
      </Box>
      <List component="nav" aria-label="Main navigation">
        {filteredMenuItems.map((item, index) => {
          if (item.divider) {
            return (
              <React.Fragment key={index}>
                <Divider sx={{ my: 1 }} />
                <Typography variant="caption" sx={{ px: 2, py: 1, fontWeight: 700, letterSpacing: 0.6, color: 'text.secondary', textTransform: 'uppercase' }}>
                  {item.section}
                </Typography>
              </React.Fragment>
            );
          }
          const active = location.pathname === item.path;
          return (
            <ListItemButton
              key={item.path}
              selected={active}
              onClick={() => { item.path && navigate(item.path); setMenuOpen(false); }}
              sx={{ borderRadius: 2, mx: 1, my: 0.25 }}
            >
              <ListItemIcon sx={{ minWidth: 40 }}>{item.icon}</ListItemIcon>
              <ListItemText
                primary={item.text}
                primaryTypographyProps={{ fontSize: '0.9rem', fontWeight: active ? 600 : 400 }}
              />
            </ListItemButton>
          );
        })}
      </List>
    </Box>
  );

  return (
    <Box sx={{ display: 'flex', minHeight: '100vh' }}>
      <AppBar
        position="fixed"
        sx={{
          bgcolor: 'background.paper',
          borderBottom: 1,
          borderColor: 'divider',
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { md: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
          <Box sx={{ flexGrow: 1 }} />
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mr: 1.5 }}>
            <Chip size="small" label="PIX" color="success" variant="outlined" sx={{ height: 22, fontSize: '0.65rem', fontWeight: 700 }} />
            <Chip size="small" label="TEF" color="success" variant="outlined" sx={{ height: 22, fontSize: '0.65rem', fontWeight: 700 }} />
          </Box>
          <Tooltip title={selectedPdv ? `${selectedPdv.nome} - ${sessaoAtiva ? 'Caixa Aberto' : 'Caixa Fechado'}` : 'Nenhum PDV selecionado'}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mr: 2, cursor: 'pointer', px: 1.5, py: 0.5, borderRadius: 2, bgcolor: 'rgba(245,168,0,0.10)', border: '1px solid rgba(245,168,0,0.20)' }}>
              <PointOfSaleIcon color="primary" fontSize="small" />
              <Typography variant="body2" sx={{ whiteSpace: 'nowrap' }}>
                {selectedPdv ? selectedPdv.codigo : 'Selecionar PDV'}
              </Typography>
            </Box>
          </Tooltip>
           <Tooltip title="Notificações de pedidos das mesas">
             <IconButton color="inherit" onClick={carregarNotificacoes} sx={{ mr: 1 }}>
               <Badge badgeContent={comandasAbertas.length} color="error">
                 <NotificationsIcon />
               </Badge>
             </IconButton>
           </Tooltip>
           <IconButton onClick={handleMenuOpen} sx={{ ml: 1 }}>
            <Avatar sx={{ width: 36, height: 36, bgcolor: 'primary.main', color: 'primary.contrastText', fontWeight: 700 }}>
              {user?.nome?.charAt(0).toUpperCase() || 'U'}
            </Avatar>
          </IconButton>
        </Toolbar>
      </AppBar>

      {/* Menu suspenso que revela ao passar o mouse na borda esquerda (desktop) */}
      <Box
        onMouseEnter={() => setMenuOpen(true)}
        onMouseLeave={() => setMenuOpen(false)}
        sx={{
          display: { xs: 'none', md: 'block' },
          position: 'fixed',
          top: 0,
          left: 0,
          height: '100vh',
          width: menuOpen ? drawerWidth : triggerWidth,
          zIndex: (theme) => theme.zIndex.drawer + 1,
          transition: 'width 220ms ease',
        }}
      >
        {!menuOpen && (
          <Box
            sx={{
              position: 'absolute',
              top: 16,
              left: 0,
              width: triggerWidth,
              height: 88,
              borderTopRightRadius: 8,
              borderBottomRightRadius: 8,
              bgcolor: 'primary.main',
              opacity: 0.75,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: 'primary.contrastText',
            }}
          >
            <ChevronRightIcon fontSize="small" />
          </Box>
        )}
        <Box
          sx={{
            width: drawerWidth,
            height: '100%',
            bgcolor: 'background.paper',
            borderRight: 1,
            borderColor: 'divider',
            overflowY: 'auto',
            transform: menuOpen ? 'translateX(0)' : 'translateX(-100%)',
            transition: 'transform 220ms ease',
            boxShadow: menuOpen ? 4 : 0,
          }}
        >
          {drawer}
        </Box>
      </Box>

      <Drawer
        variant="temporary"
        open={mobileOpen}
        onClose={handleDrawerToggle}
        ModalProps={{ keepMounted: true }}
        sx={{
          display: { xs: 'block', md: 'none' },
          '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
        }}
      >
        {drawer}
      </Drawer>

      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 3,
          width: '100%',
          mt: '64px',
          bgcolor: 'background.default',
          minHeight: 'calc(100vh - 64px)',
        }}
      >
        <Outlet />
      </Box>

<Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={handleMenuClose} transformOrigin={{ horizontal: 'right', vertical: 'top' }} anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}>
          <MenuItem onClick={() => { handleMenuClose(); navigate('/perfil'); }}>
            <ListItemIcon><PersonIcon fontSize="small" /></ListItemIcon>
            Perfil
          </MenuItem>
          <MenuItem onClick={() => { handleMenuClose(); navigate('/usuario'); }}>
            <ListItemIcon><CashIcon fontSize="small" /></ListItemIcon>
            Usuário e Caixa
          </MenuItem>
          <MenuItem onClick={handleLogout}>
            <ListItemIcon><LogoutIcon fontSize="small" /></ListItemIcon>
            Sair
          </MenuItem>
        </Menu>

       {/* Dialog de Notificações de Pedidos das Mesas */}
       <Dialog open={notifOpen} onClose={() => { setNotifOpen(false); setSelectedComanda(null); }} maxWidth="sm" fullWidth>
         <DialogTitle>Notificações — Pedidos das Mesas</DialogTitle>
         <DialogContent>
           {selectedComanda ? (
             <Box>
               <Button size="small" onClick={() => setSelectedComanda(null)} sx={{ mb: 2 }}>← Voltar para lista</Button>
               <Typography variant="h6" gutterBottom>Comanda #{selectedComanda.numero} — Cliente: {selectedComanda.clienteNome || 'Geral'}</Typography>
               <Typography variant="body2" color="text.secondary" gutterBottom>Subtotal: R$ {selectedComanda.subtotal?.toFixed(2) || '0,00'}</Typography>
               <Divider sx={{ my: 1.5 }} />
               <Typography variant="subtitle2" gutterBottom>Itens Pedidos:</Typography>
               {itensComanda.map((it: any) => (
                 <Box key={it.id} sx={{ display: 'flex', justifyContent: 'space-between', py: 0.75, borderBottom: 1, borderColor: 'divider' }}>
                   <Typography variant="body2">{it.quantidade}x {it.nomeProduto}</Typography>
                   <Typography variant="body2" fontWeight={600}>R$ {it.valorTotal?.toFixed(2)}</Typography>
                 </Box>
               ))}
               {itensComanda.length === 0 && <Typography variant="body2" color="text.secondary">Nenhum item nesta comanda.</Typography>}
             </Box>
           ) : (
             <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, mt: 1 }}>
               <Typography variant="body2" color="text.secondary" gutterBottom>Comandas abertas aguardando atendimento ou fechamento:</Typography>
               {comandasAbertas.map((c: any) => (
                 <Paper key={c.id} variant="outlined" sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                   <Box>
                     <Typography variant="subtitle1" fontWeight={600}>Comanda #{c.numero} — {c.clienteNome || 'Cliente Mesa'}</Typography>
                     <Typography variant="caption" color="text.secondary">Total: R$ {c.valorTotal?.toFixed(2) || '0,00'}</Typography>
                   </Box>
                   <Button variant="contained" size="small" onClick={() => verDetalhesComanda(c)}>Ver Pedidos</Button>
                 </Paper>
               ))}
               {comandasAbertas.length === 0 && (
                 <Typography variant="body2" color="text.secondary" sx={{ py: 3, textAlign: 'center' }}>
                   Nenhuma comanda ou pedido ativo no momento.
                 </Typography>
               )}
             </Box>
           )}
         </DialogContent>
         <DialogActions>
           <Button onClick={() => { setNotifOpen(false); setSelectedComanda(null); }}>Fechar</Button>
         </DialogActions>
       </Dialog>
     </Box>
   );
 }
